"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7781],{63084:e=>{e.exports=JSON.parse('{"functions":[{"name":"ChooseStart","desc":"Skips the run of leading plain `Walk` steps that sit within `skipDistance` of `position`,\\nbecause a navmesh path starts where the agent already stands. A labelled, `Jump` or `Custom`\\nstep is never skipped, even one under the agent: it carries meaning (a door at the agent\'s\\nfeet) that `StepReached` must report. The last step is never skipped either, so there is\\nalways something to walk toward and arrival is always reported from `MoveToFinished`.","params":[{"name":"path","desc":"","lua_type":"Path"},{"name":"position","desc":"Where the rig is.","lua_type":"Vector3"},{"name":"skipDistance","desc":"Horizontal distance within which a leading step is already reached.","lua_type":"number"}],"returns":[{"desc":"The index of the first step to walk toward; `#path + 1` only when the path is empty.","lua_type":"number"}],"function_type":"static","source":{"line":138,"path":"lib/Movers/Humanoid.luau"}},{"name":"new","desc":"Sets `WalkSpeed` to `Speed` and, with `ServerOwned`, hands the root to the server. That fails,\\nwith a warning, unless the model is a descendant of Workspace and unanchored before this call.","params":[{"name":"model","desc":"Needs a `PrimaryPart` and a `Humanoid` child.","lua_type":"Model"},{"name":"options","desc":"","lua_type":"HumanoidOptions?"}],"returns":[{"desc":"","lua_type":"HumanoidMover"}],"function_type":"static","errors":[{"lua_type":"string","desc":"The model has no `PrimaryPart` or no `Humanoid`."},{"lua_type":"\\"unknown option\\"","desc":"A key that is not in `HumanoidOptions`."}],"source":{"line":165,"path":"lib/Movers/Humanoid.luau"}},{"name":"Follow","desc":"Starts along `path`, replacing any current one. The replaced path gets `Arrived(false)` before\\nthe new one starts; the new one is only ever reported from a later frame. An empty path is\\nreported as `Arrived(false)` on the next Heartbeat.","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"},{"name":"path","desc":"","lua_type":"Path"}],"returns":[],"function_type":"static","source":{"line":389,"path":"lib/Movers/Humanoid.luau"}},{"name":"Stop","desc":"Cancels the walk. Fires `Arrived(false)` if a path was in progress.","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"}],"returns":[],"function_type":"static","source":{"line":424,"path":"lib/Movers/Humanoid.luau"}},{"name":"Face","desc":"Turns the root toward `position` every Heartbeat while no path is in progress, so a rig can\\nstare at a player without walking. `MoveTo` steers while walking, so a path takes over and\\nthe facing resumes when it ends. Sets the root\'s `CFrame`, which is what a server-owned rig\\nstanding still expects.","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"},{"name":"position","desc":"Where to face; `nil` to stop.","lua_type":"Vector3?"}],"returns":[],"function_type":"static","source":{"line":437,"path":"lib/Movers/Humanoid.luau"}},{"name":"SetNudge","desc":"A sideways push from a steering sense such as [Neighbours]. Re-issues the current `MoveTo`\\nwhen the nudge changes, so the rig turns at once.","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"},{"name":"offset","desc":"Added to every step but the last; `nil` clears.","lua_type":"Vector3?"}],"returns":[],"function_type":"static","source":{"line":469,"path":"lib/Movers/Humanoid.luau"}},{"name":"Teleport","desc":"Drops the current path (`Arrived(false)` if one was in progress) and pivots the model so its\\nroot sits at `position`, keeping its facing.","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"},{"name":"position","desc":"Where the root goes.","lua_type":"Vector3"}],"returns":[],"function_type":"static","source":{"line":488,"path":"lib/Movers/Humanoid.luau"}},{"name":"GetPosition","desc":"","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"}],"returns":[{"desc":"The `PrimaryPart` position.","lua_type":"Vector3"}],"function_type":"static","source":{"line":501,"path":"lib/Movers/Humanoid.luau"}},{"name":"GetSpeed","desc":"","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"}],"returns":[{"desc":"Studs per second.","lua_type":"number"}],"function_type":"static","source":{"line":509,"path":"lib/Movers/Humanoid.luau"}},{"name":"SetSpeed","desc":"","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"},{"name":"studsPerSecond","desc":"Becomes the humanoid\'s `WalkSpeed`.","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":517,"path":"lib/Movers/Humanoid.luau"}},{"name":"IsMoving","desc":"","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"}],"returns":[{"desc":"`true` while a path is in progress.","lua_type":"boolean"}],"function_type":"static","source":{"line":526,"path":"lib/Movers/Humanoid.luau"}},{"name":"Destroy","desc":"Stops, then drops the signals. The model is left alone; it is yours.","params":[{"name":"self","desc":"","lua_type":"HumanoidMover"}],"returns":[],"function_type":"static","source":{"line":535,"path":"lib/Movers/Humanoid.luau"}}],"properties":[],"types":[{"name":"HumanoidOptions","desc":"","fields":[{"name":"Speed","lua_type":"number?","desc":"`WalkSpeed`, studs per second. Default `16`."},{"name":"StuckTimeout","lua_type":"number?","desc":"Seconds without moving `StuckDistance` before giving up. Default `3`."},{"name":"StuckDistance","lua_type":"number?","desc":"Studs the root must move within `StuckTimeout` to count as progress. Default `0.5`."},{"name":"SkipDistance","lua_type":"number?","desc":"Leading plain Walk steps within this horizontal distance of the rig are skipped. Default `1`."},{"name":"ServerOwned","lua_type":"boolean?","desc":"Set the root\'s network owner to the server in `new`. Default `true`."},{"name":"Noise","lua_type":"MoverNoise?","desc":"Fire a [Hearing] noise signal every `Interval` seconds while walking, so other agents hear this one coming. Off by default."}],"source":{"line":83,"path":"lib/Movers/Humanoid.luau"}},{"name":"MoverNoise","desc":"","fields":[{"name":"Signal","lua_type":"Signal<(Vector3, number?)>","desc":"The noise signal a [Hearing] sense listens to."},{"name":"Interval","lua_type":"number?","desc":"Seconds between noises while moving. Default `0.5`."},{"name":"Loudness","lua_type":"number | (speed: number) -> number?","desc":"The loudness fired, or a function of the current speed. Default `1`."}],"source":{"line":91,"path":"lib/Movers/Humanoid.luau"}}],"name":"HumanoidMover","desc":"A [Types.Mover] for a model with a `Humanoid` and a `PrimaryPart`: walks each step with\\n`MoveTo`, jumps at `Jump` steps, and gives up when the rig stops making progress for\\n`StuckTimeout` seconds. Exposed as `VluxyAI.Movers.Humanoid`.\\n\\nRoblox fires `MoveToFinished(false)` eight seconds after any `MoveTo`, reached or not, so a step\\nfurther than eight seconds of walking would otherwise end a healthy walk. The mover re-issues\\nthe `MoveTo` for the same step while the stuck check sees progress and only gives up when the\\nstuck check agrees.\\n\\nFollows the two mover rules: `Follow` fires `Arrived(false)` for the path it replaces before\\nstarting the new one, and the new path is only ever reported from a later frame, because\\n`MoveToFinished` never fires inside `MoveTo`.","source":{"line":122,"path":"lib/Movers/Humanoid.luau"}}')}}]);